-- 全培養費の排水側帰属と循環回収の条件付き最小構成。DMLのみ。一度だけ適用。
begin;
select set_config('amd.cost_change_reason','まさ指示: 全培養費を燃料から除外、排水側に光源、循環回収は追加購入のみ',true);
do $$ begin
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_model_id)) from project_cost_models t where cost_model_id='cm_p21_fuel_260914') is distinct from '2d7d6764825e8b3a2489a5e4908b6d28' then raise exception 'fuel changed: model'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_fuel_260914') is distinct from '839a61c316e429a16a486233e27b323f' then raise exception 'fuel changed: assumptions'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_item_id)) from project_cost_items t where cost_model_id='cm_p21_fuel_260914') is distinct from '37269b68b120e3efdb272054f91cdcad' then raise exception 'fuel changed: items'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_task_id)) from project_cost_tasks t where cost_model_id='cm_p21_fuel_260914') is distinct from 'e70f8ccf8c7eb05ef1b3aa91d13b0910' then raise exception 'fuel changed: tasks'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_note_id)) from project_cost_notes t where cost_model_id='cm_p21_fuel_260914') is distinct from '0805aa221415ac2b7680f617601e67c3' then raise exception 'fuel changed: notes'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_model_id)) from project_cost_models t where cost_model_id='cm_p21_260820') is distinct from '646a54dd085eb5a986e03213ac25c39b' then raise exception 'effluent changed: model'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_260820') is distinct from '0fcd1c6c7f000ab8d00d11ac4f1396d2' then raise exception 'effluent changed: assumptions'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_item_id)) from project_cost_items t where cost_model_id='cm_p21_260820') is distinct from '8a82af951db31798524de4472ad50491' then raise exception 'effluent changed: items'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_task_id)) from project_cost_tasks t where cost_model_id='cm_p21_260820') is distinct from 'cb0f3db0ded0cf0155a0da558f06a9a2' then raise exception 'effluent changed: tasks'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_note_id)) from project_cost_notes t where cost_model_id='cm_p21_260820') is distinct from '2d3d6661f62fd0704c3127d56a8465ae' then raise exception 'effluent changed: notes'; end if;
end $$;
update project_cost_models set summary_md='出荷待ち菌体を利用し全培養費を排水側へ帰属。光源は排水側を参照。燃料側は脂肪酸回収・FAME化・分析・出荷で増える費用だけを計上。',version_label='261017 全培養費を排水側・回収の最小構成',system_scope_md='培養設備・照明・CO₂・培地・通常作業・送気前処理は燃料側0。循環回収は改造60・ポンプ80・配管60・計装40・据付60＝300万円、年保守9万円。既存の接触部・アルカリ再生/受槽・酸析/FAME設備・約21m³の溶媒保持能力を共用できる条件。保有・空き・材質・能力は未確認。不足分を追加購入欄へ入力。培養液の追加送液電力は既存循環を変えず使える条件で0、溶媒循環/再生の追加電力は計上。正味濃度差0.8kg/m³・30分・損失0.005%は実証前。',updated_at=now() where cost_model_id='cm_p21_fuel_260914';
update project_cost_assumptions set note='在庫利用では培養用送気・前処理費を全額排水事業へ帰属。旧年120万円を除外。この欄は燃料専用培養時だけ計上。',label='専用培養の送気・前処理費',value=0,updated_at=now() where cost_assumption_id='caf_auto_carbon_delivery_annual';
update project_cost_assumptions set note='追加購入300万円の年3%を仮置き。既存設備の通常保守は排水側。追加点検清掃24人時は作業欄で別計上。交換頻度は実測で見直す。',value=90000,updated_at=now() where cost_assumption_id='caf_loop_loop_annual';
update project_cost_assumptions set note='旧1500万円は接触600・再生分離400・受槽配管制御据付500万円の内部予算で、業者見積なし。明細導入後は各追加装置の合計を使い、この値は加算しない。',label='循環回収の旧一式予算（現在は参照のみ）',value=3000000,updated_at=now() where cost_assumption_id='caf_loop_loop_capex';
update project_cost_assumptions set note='最小構成は既存槽の撹拌・循環・接触部を共用し追加揚程なしを条件に0。水側必要接触量約1525m³/hは新設ポンプ仕様ではない。外付け抽出・前ろ過や追加揚程が要れば電力と設備能力不足分を入力。',label='回収で増える培養液送液・前ろ過の電力',value=0,updated_at=now() where cost_assumption_id='caf_loop_water_power';
update project_cost_assumptions set note='全培養費を排水側で計上。在庫回収ではこの旧配賦入力を使わない。',updated_at=now() where cost_assumption_id='caf_op_inventory_common_allocation_annual';
update project_cost_assumptions set note='旧350万円は送気・前処理の培養設備なので全額除外。照明・CO₂・培地・菌体生産設備は排水側。回収・FAME化だけの追加購入があれば入力。既存の保有・能力は現物未確認。',label='回収・燃料化のその他追加設備（培養設備を除く）',value=0,updated_at=now() where cost_assumption_id='caf_shared_inventory_equipment_capex';
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'既存の溶媒接触・スキマーが必要面積と流量を満たす条件で改造のみ。新規大型接触器や膜モジュールは含まない。','円','既存接触部の改造・分配器','AMD（内部）',600000,true,null,'fuel_solvent_contact_capex','H',170,null,'amd_internal',null,'循環回収の追加購入','仮置き','cm_p21_fuel_260914','caf_min_contact');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'溶媒側約38m³/hの循環を想定した内部予算。小型実験用ポンプでは不足。実揚程・粘度・温度・接液材を選定して見積更新。','円','追加の溶媒用ポンプ','AMD（内部）',800000,true,null,'fuel_solvent_pump_capex','H',171,null,'amd_internal',null,'循環回収の追加購入','仮置き','cm_p21_fuel_260914','caf_min_pump');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'既存拠点内の短距離配管・弁・溶媒受け皿の追加予算。全槽への長距離配管は別見積。','円','戻り配管・弁・受け皿','AMD（内部）',600000,true,null,'fuel_solvent_pipe_capex','H',172,null,'amd_internal',null,'循環回収の追加購入','仮置き','cm_p21_fuel_260914','caf_min_pipe');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'既存制御盤を共用するセンサー・インターロック追加の内部予算。','円','液面・漏れ検知と制御追加','AMD（内部）',400000,true,null,'fuel_solvent_control_capex','H',173,null,'amd_internal',null,'循環回収の追加購入','仮置き','cm_p21_fuel_260914','caf_min_control');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'既存設備への改造と試運転の内部予算。建屋・大規模基礎工事は含まない。','円','取付・接続・試運転','AMD（内部）',600000,true,null,'fuel_solvent_install_capex','H',174,null,'amd_internal',null,'循環回収の追加購入','仮置き','cm_p21_fuel_260914','caf_min_install');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'最小構成の条件付き0。アルカリ接触槽・相分離/受槽・酸析・FAME化・加温冷却・溶媒保持約21m³に必要な既存設備の保有、空き、材質、能力は未確認。機能を削る意味ではなく、不足設備の追加購入額をここへ入力。','円','既存能力の不足分を補う設備','AMD（内部）',0,true,null,'fuel_solvent_capacity_capex','H',175,null,'amd_internal',null,'循環回収の追加購入','仮置き','cm_p21_fuel_260914','caf_min_capacity');
update project_cost_notes set title='513時点の送気概算（培養費のため燃料から除外）',body_md='現在の在庫回収では、ここに記した装置350万円と年120万円は培養費として燃料側から全額除外。以下は旧概算の履歴。

基準条件の脂肪酸約109.8t/年に対しCO₂供給3.48kg/kg（吸収約80%の旧仮定）、排ガスCO₂5%で約389万Nm³/年。年間300日×日中12時間なら約1081Nm³/h。差圧20kPa・効率55%で約3.93万kWh/年→電力70万円、追い冷却・凝縮水/フィルタ25万円、部品・保守25万円。購入予算は送気100万円＋前処理80万円＋配管70万円＋制御50万円＋据付50万円＝350万円。既設の冷却・除塵後から近距離分岐する想定で、濃縮CO₂購入・新規分離濃縮・大規模脱硫・長距離送気は含まない。差圧と吸収率は実測前、ブロワ性能や必要台数を保証する見積ではない。空気は同じ炭素量に約125倍のガス量が必要なので、この年額をそのまま流用せず再見積する。' where cost_note_id='cnf_est_gas_261017';
update project_cost_notes set title='全培養費を排水側へ帰属し、回収・転換の追加費を比較',body_md='在庫回収は排水側の光源・年間生産性を参照し、培養費を再計上しない。燃料側では回収の循環条件、装置の追加購入明細、FAME転換、分析、出荷の費用を変更する。既存能力不足の追加購入は専用欄へ入力。光源による生産量の変化と照明費の二重計上を区別する。専用培養へ切り替えたときだけ燃料側に光源・炭素源の設定と費用が戻る。' where cost_note_id='cnf_guide';
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_min_boundary_261017','cm_p21_fuel_260914','caveat','培養費の帰属と最小構成の成立条件','培養設備・照明・CO₂・培地・通常作業・送気前処理は燃料側0。循環回収は改造60・ポンプ80・配管60・計装40・据付60＝300万円、年保守9万円。既存の接触部・アルカリ再生/受槽・酸析/FAME設備・約21m³の溶媒保持能力を共用できる条件。保有・空き・材質・能力は未確認。不足分を追加購入欄へ入力。培養液の追加送液電力は既存循環を変えず使える条件で0、溶媒循環/再生の追加電力は計上。正味濃度差0.8kg/m³・30分・損失0.005%は実証前。','内部設計・要実測見積',null,'amd_internal',32);
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_solvent_purpose_261017','cm_p21_fuel_260914','reading_guide','溶媒を使う目的','培養液中の薄い脂肪酸を溶媒へ移し、アルカリ水へ渡して濃縮し、再生した溶媒を戻す。脂肪酸蓄積による菌体負担を抑える狙いもある。燃料原料や栄養ではなく回収媒体。消耗分だけ補給。溶媒なしの浮上分離・吸着等も候補だが、SOL株での性能は未確認。全槽5%保持は必須ではない。','Kato2017','https://link.springer.com/article/10.1186/s13068-017-0831-z','amd_internal',33);
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_physical_recovery_261017','cm_p21_fuel_260914','caveat','溶媒なしの物理回収を先に評価する','水面に油層や粒子が集まるなら、静置・スキマー・ろ過等の物理回収が候補。Liu2011の図4は分泌脂肪酸の白い粒状物が水面より上の容器壁へ堆積した例で、堆積物は約60%水、乾燥分の約半分が脂肪酸。純油の自然分離や工業回収率を保証するものではない。実際の株・温度・pHで浮上/沈降/付着/分散、回収率、水分と菌体混入を確認する。現在の循環回収は溶媒を用いる方式の比較であり必須設備ではない。溶媒添加で分泌が促進したKato2017の速度0.036g/L/日を、溶媒なしへそのまま流用して原価確定しない。','Kato2017','https://pmc.ncbi.nlm.nih.gov/articles/PMC3084101/','amd_internal',34);
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'全培養費は排水事業で負担。太陽光主体ではLED器具・電力とLED由来冷却電力を除き、生産性比率で必要培養系列数を増やす。顧客の処理槽には適用しない。屋外化・敷地・季節冷却等の未見積費は追加年額換算へ入力。',null,'菌体の製造拠点の光源','AMD（内部）',null,true,null,'culture_light_source','H',38,'sunlight','amd_internal',null,'菌体の製造拠点の光源','仮置き','cm_p21_260820','ca_light_source');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'夜間・曇天・季節を含む仮定。株別・場所別の実測ではない。排水側の必要培養系列数と出荷待ち中の燃料分泌量に反映。増殖と分泌の応答が同一との仮定は実測で分ける。','％','太陽光での年間培養生産性（人工照明比）','AMD（内部）',50,true,null,'culture_sunlight_productivity_ratio','H',39,null,'amd_internal',null,'菌体の製造拠点の光源','仮置き','cm_p21_260820','ca_light_productivity');
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cn_light_boundary_261017','cm_p21_260820','caveat','培養光源と副産物燃料の費用境界','製造拠点の光源を切り替え全培養費を排水側へ計上。燃料の出荷待ち回収は同じ光源と生産性を参照し、照明・CO₂・送気・培地費は再計上しない。排水へ供給する菌体量は需要から決まり、太陽光で生産性が下がると必要培養系列数は増える。待ち期間中の分泌量が変わるため燃料1L原価は変わりうる。屋外化・冬季運転・株別生産性は未見積/実証前。','内部設計・要実測見積',null,'amd_internal',90);
commit;
